const H = (st, px) => Math.round(px * st.hscale);
const tint = (pct, v = "primary") => `color-mix(in oklab,var(--${v}) ${pct}%,var(--surface))`;
const PEOPLE = { LP: "Lin Park", SA: "Sam Achebe", PN: "Priya Nair", TR: "Teodora Ruiz", JW: "Jonah Weiss", MO: "Mara Okafor", IV: "Ilse Varga", RM: "Ravi Menon", OL: "Oskar Lind" };
const KI = { LP: 0, SA: 1, PN: 2, TR: 3, JW: 4, MO: 5, IV: 1, RM: 2, OL: 3 };
const av = (ini, s = 26) => { const k = KI[ini] || 0, v = k % 2 ? "accent" : "primary"; return `<span title="${PEOPLE[ini] || ini}" style="flex:none;width:${s}px;height:${s}px;border-radius:50%;display:inline-grid;place-items:center;font:600 ${Math.round(s * 0.38)}px var(--font-b);background:${tint(16 + (k % 3) * 7, v)};color:color-mix(in oklab,var(--${v}) 72%,var(--text))">${ini}</span>`; };
const avs = (list, s = 26) => `<span style="display:inline-flex">${list.map((x, i) => `<span style="margin-left:${i ? -7 : 0}px;border-radius:50%;box-shadow:0 0 0 2px var(--surface);display:inline-flex">${av(x, s)}</span>`).join("")}</span>`;
const chip = (t, on, h = 30) => `<span style="display:inline-flex;align-items:center;gap:6px;height:${h}px;padding:0 12px;border-radius:999px;font-size:12.5px;font-weight:500;white-space:nowrap;flex:none;${on ? "background:var(--primary);color:var(--on-primary);border:1px solid var(--primary)" : "border:1px solid var(--border);background:var(--surface)"}">${t}</span>`;
const seg = (items, on, h = 32) => `<div style="display:inline-flex;flex:none;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:var(--surface)">${items.map((t, i) => `<span style="height:${h}px;padding:0 12px;display:flex;align-items:center;gap:6px;font-size:12.5px;font-weight:500;white-space:nowrap;${i ? "border-left:1px solid var(--border);" : ""}${i === on ? "background:var(--primary);color:var(--on-primary)" : ""}">${t}</span>`).join("")}</div>`;
const sb = (t, k = "accent") => `<span style="display:inline-flex;align-items:center;gap:4px;height:20px;padding:0 8px;border-radius:999px;font:600 11px var(--font-b);white-space:nowrap;flex:none;background:color-mix(in oklab,var(--${k}) 14%,var(--surface));color:color-mix(in oklab,var(--${k}) 78%,var(--text))">${t}</span>`;
const ib = (n, s = 15, on, w = 34) => `<span class="btn" style="width:${w}px;height:${w}px;padding:0;flex:none${on ? `;background:${tint(16)};border-color:var(--primary);color:var(--primary)` : ""}">${ic(n, s)}</span>`;
const pbar = (f, k = "primary", h = 6) => `<div style="height:${h}px;border-radius:${h}px;background:color-mix(in oklab,var(--muted) 16%,var(--surface));overflow:hidden"><div style="height:100%;width:${Math.round(f * 100)}%;background:var(--${k});border-radius:${h}px"></div></div>`;
const topbar = (title, right = "", q = "Search") => `<div class="top"><div style="font-weight:600;font-size:15px;display:flex;align-items:center;gap:8px;white-space:nowrap">${title}</div><div class="search">${ic("search", 15)}${q}</div>${right}<span style="display:flex;color:var(--muted)">${ic("bell", 19)}</span></div>`;
const vsep = `<span style="width:1px;height:22px;background:var(--border);flex:none"></span>`;
const hatch = `repeating-linear-gradient(135deg,color-mix(in oklab,var(--muted) 12%,var(--surface)) 0 5px,var(--surface) 5px 10px)`;
const money = (n) => "$" + n.toLocaleString("en-US");
const lbl = (t) => `<div style="font:600 11px var(--font-b);text-transform:uppercase;letter-spacing:.06em;color:var(--muted)">${t}</div>`;
const mtop = (left, title, right, st) => `<div class="mtop" style="gap:10px"><span style="display:flex;align-items:center;gap:10px;min-width:0">${left}<b style="font-size:${H(st, 17)}px;font-family:var(--font-h);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${title}</b></span><span style="display:flex;gap:8px;align-items:center;flex:none">${right}</span></div>`;
