const photo = (id, boat) => `<svg viewBox="0 0 800 520" width="100%" height="100%" preserveAspectRatio="xMidYMid slice" style="display:block"><defs><linearGradient id="${id}s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2d3b68"/><stop offset=".58" stop-color="#e48f6a"/><stop offset="1" stop-color="#f5c898"/></linearGradient><linearGradient id="${id}w" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d4886b"/><stop offset="1" stop-color="#28334e"/></linearGradient></defs>
<rect width="800" height="520" fill="url(#${id}s)"/><circle cx="560" cy="262" r="44" fill="#fbe3b8"/><path d="M0 300L120 222L210 268L330 182L460 282L560 234L680 292L800 246V350H0Z" fill="#3d405f"/><path d="M0 334L150 272L300 322L420 284L600 332L800 304V362H0Z" fill="#2c2f48"/><rect y="352" width="800" height="168" fill="url(#${id}w)"/><path d="M480 376h150M510 400h90M530 424h50" stroke="#fbe3b8" stroke-width="4" opacity=".5"/>
${boat ? `<path d="M240 436h132l-20 24h-92z" fill="#1c2033"/><path d="M304 436V346" stroke="#1c2033" stroke-width="4"/><path d="M308 352l52 78h-52z" fill="#f2e6d4"/><path d="M300 360l-40 70h40z" fill="#c9b9a2"/>` : ""}</svg>`;
const slider = (label, v, disp, min = -100, max = 100) => { const f = (v - min) / (max - min), z = min < 0 ? 0.5 : 0, a = Math.min(f, z), b = Math.max(f, z);
  return `<div style="display:grid;gap:7px"><div style="display:flex;justify-content:space-between;font-size:12.5px"><span>${label}</span><span class="num" style="font-size:12px">${disp != null ? disp : (v > 0 && min < 0 ? "+" : "") + v}</span></div><div style="position:relative;height:4px;border-radius:2px;background:color-mix(in oklab,var(--muted) 22%,var(--surface))"><span style="position:absolute;left:${a * 100}%;width:${(b - a) * 100}%;top:0;bottom:0;background:var(--primary);border-radius:2px"></span><span style="position:absolute;left:calc(${f * 100}% - 7px);top:-5px;width:14px;height:14px;border-radius:50%;background:var(--surface);border:2px solid var(--primary)"></span></div></div>`; };
const histo = (rnd, w = 268, h = 70) => { const mk = (sh) => { const pts = Array.from({ length: 33 }, (_, i) => { const x = i / 32; return Math.max(0.04, Math.exp(-Math.pow((x - sh) * 3.2, 2)) * 0.8 + rnd() * 0.18); }); return `M0 ${h} ` + pts.map((v, i) => `L${(i / 32 * w).toFixed(1)} ${(h - v * h).toFixed(1)}`).join(" ") + ` L${w} ${h}Z`; };
  return `<svg width="100%" height="${h}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path d="${mk(0.35)}" fill="color-mix(in oklab,var(--primary) 40%,transparent)"/><path d="${mk(0.62)}" fill="color-mix(in oklab,var(--accent) 40%,transparent)"/><path d="${mk(0.5)}" fill="color-mix(in oklab,var(--muted) 30%,transparent)"/></svg>`; };
