const LAYERS = [["gw_text", "Title · “Low tide”", "Text", 100, 1, 0], ["", "Boat · cutout", "Normal", 100, 1, 0, "boat"], ["gw_sliders", "Warm glow", "Soft light", 62, 1, 0], ["", "Sky lift", "Screen", 40, 0, 0, "sky"], ["", "Background · Harbour at dusk", "Normal", 100, 1, 1, "bg"]];
