const DIFF = [["=", "Refund policy"], ["~", "Last updated: 3 November 2026", "Last updated: 7 November 2026", "3", "7"], ["=", "We want every team to be happy with Fernway."],
  ["~", "You can ask for a refund within 14 days of your first payment.", "You can ask for a refund within 30 days of your first payment.", "14", "30"],
  ["-", "Refunds are paid as account credit."], ["+", null, "Refunds go back to the original payment method in 5–10 working days."], ["=", "Annual plans"],
  ["~", "Annual plans can be cancelled at any time but are not refunded.", "Annual plans cancelled in the first 30 days get a pro-rated refund.", "can be cancelled at any time but are not refunded", "cancelled in the first 30 days get a pro-rated refund"],
  ["+", null, "After 30 days, your plan stays active until the end of the paid term."], ["=", "Seats you remove mid-cycle are credited on your next invoice."],
  ["-", "Refund requests must be sent by post."], ["+", null, "Ask for a refund from Settings → Billing, or email the billing team."], ["=", "What is not refunded"], ["=", "Add-on storage bought in the last 7 days."],
  ["~", "Accounts closed for breaking the terms of use.", "Accounts closed for breaking the terms of service.", "use", "service"]];
const word = (s, w, k) => w ? s.replace(w, `<mark style="background:color-mix(in oklab,var(--${k}) 32%,transparent);color:inherit;border-radius:2px;padding:0 1px">${w}</mark>`) : s;
const lineBg = (k) => `background:color-mix(in oklab,var(--${k}) 11%,var(--surface))`;
const sideRows = () => { let a = 0, b = 0; return DIFF.map(([op, l, r, ow, nw]) => { const L = op === "+" ? null : l, R = op === "-" ? null : (op === "=" ? l : r); if (L != null) a++; if (R != null) b++;
  const cellF = (txt, n, k, w, sign) => txt == null ? `<div style="background:${hatch}"></div>` : `<div style="display:grid;grid-template-columns:38px 16px 1fr;align-items:start;padding:5px 0;${k ? lineBg(k) : ""}"><span class="muted num" style="font-size:11.5px;text-align:right;padding-right:8px;font-weight:500">${n}</span><span style="font-weight:700;color:var(--${k || "muted"})">${sign}</span><span style="padding-right:12px;${op === "=" && (txt === "Refund policy" || txt === "Annual plans" || txt === "What is not refunded") ? "font-weight:700" : ""}">${word(txt, w, k)}</span></div>`;
  return `<div style="display:grid;grid-template-columns:1fr 1fr;font-size:13px;line-height:1.5"><div style="border-right:1px solid var(--border);display:grid">${cellF(L, a, op === "=" ? "" : "danger", ow, op === "=" ? "" : "−")}</div><div style="display:grid">${cellF(R, b, op === "=" ? "" : "success", nw, op === "=" ? "" : "+")}</div></div>`; }).join(""); };
const CHANGES = [["~", "Last updated date", "line 2"], ["~", "Refund window 14 → 30 days", "line 4"], ["±", "Account credit → original payment method", "line 5"], ["~", "Annual plans: pro-rated refund in 30 days", "line 7"], ["+", "Plan stays active to end of term", "line 8"], ["±", "Request by post → Settings or email", "line 10"], ["~", "“terms of use” → “terms of service”", "line 14"]];
const VERS = [["v14", "Sam Achebe", "7 Nov · 16:20", "Updated refund window and steps", "SA", "Current"], ["v13", "Teodora Ruiz", "5 Nov · 11:05", "Tidied annual plans section", "TR"], ["v12", "Teodora Ruiz", "3 Nov · 09:41", "Legal review edits", "TR", "Base"], ["v11", "Mara Okafor", "28 Oct · 17:12", "Added storage exclusion", "MO"], ["v10", "Sam Achebe", "21 Oct · 10:30", "First published", "SA"]];
